class RecurrentGPT(nn.Module):  # Block = nanoGPT's Block (pre-norm attention + MLP)
    def __init__(s, d=64, h=4):
        super().__init__()
        s.lhs = nn.Embedding(PAD + 1, d); s.rhs = nn.Embedding(PAD + 1, d)
        s.prelude = Block(d, h)                           # runs once
        s.adapter = nn.Linear(2 * d, d)                   # concat(s, e), then project to d
        s.core = nn.Sequential(Block(d, h), Block(d, h))  # the looped part
        s.core_ln = nn.LayerNorm(d)                       # keeps the state's scale fixed
        s.coda = Block(d, h); s.ln_f = nn.LayerNorm(d)
        s.head = nn.Linear(d, 10)                         # one digit per line

    def step(s, st, e):
        return s.core_ln(s.core(s.adapter(torch.cat([st, e], -1))))

    def forward(s, lhs, rhs, n_no_grad, n_grad):
        e = s.prelude(s.lhs(lhs) + s.rhs(rhs))  # no position embedding
        st = torch.randn_like(e)                # s0 = noise
        with torch.no_grad():
            for _ in range(n_no_grad): st = s.step(st, e)
        for _ in range(n_grad): st = s.step(st, e)
        return s.head(s.ln_f(s.coda(st)))

def latent_recursion(x, y, z, n=6):
    for i in range(n):
        z = net(x, y, z)        # think: refine latent z
    y = net(y, z)               # act: refine answer y
    return y, z

def deep_recursion(x, y, z, n=6, T=3):
    with torch.no_grad():       # T-1 passes, no graph
        for j in range(T - 1):
            y, z = latent_recursion(x, y, z, n)
    y, z = latent_recursion(x, y, z, n)  # backprop here
    return (y.detach(), z.detach()), head(y), q_head(y)

